from robot.libraries import BuiltIn
from robot.libraries.BuiltIn import RobotNotRunningError
import logging


logger = logging.getLogger()
TL_CONFIG = None


def get_cu_master_node_ssh_details(gnb_id=0):
    """
    Retrieves the ssh connection details for the cloud hosting CU master node
    from the testline configuration.
    """
    tl_config = get_testline_configuration()
    return tl_config.gnbs[gnb_id].cloud_deployment.cloud_hosting.master_node.ssh_connection_details


def get_vdu_master_node_ssh_details(gnb_id=0, vdu_id=0):
    """
    Retrieves the ssh connection details for the cloud hosting VDU master node
    from the testline configuration.
    """
    tl_config = get_testline_configuration()
    return tl_config.gnbs[gnb_id].dus[vdu_id].cloud_deployment.cloud_hosting.master_node.ssh_connection_details


def get_vdu_namespace(gnb_id, vdu_id):
    """
    Return the namespace for the VDU
    """
    tl_config = get_testline_configuration()
    return tl_config.gnbs[gnb_id].dus[vdu_id].cloud_deployment.cloud_hosting.namespace


def get_cu_namespace(gnb_id):
    """
    Return the namespace for the CU
    """
    tl_config = get_testline_configuration()
    return tl_config.gnbs[gnb_id].cloud_deployment.cloud_hosting.namespace


def get_k8s_cu_proxy(gnb_id):
    """
    Get network proxy to access CU nodes.
    """
    tl_config = get_testline_configuration()
    cu_master_node = tl_config.gnbs[gnb_id].cloud_deployment.cloud_hosting.master_node
    return {'host': cu_master_node.k8s_connection_details.ip_addr,
            'user': cu_master_node.k8s_connection_details.username,
            'password': cu_master_node.k8s_connection_details.password}


def get_k8s_vdu_proxy(gnb_id, vdu_id):
    """
    Get network proxy to access VDU nodes.
    """
    tl_config = get_testline_configuration()
    vdu_master_node = tl_config.gnbs[gnb_id].dus[vdu_id].cloud_deployment.cloud_hosting.master_node
    return {'host': vdu_master_node.k8s_connection_details.ip_addr,
            'user': vdu_master_node.k8s_connection_details.username,
            'password': vdu_master_node.k8s_connection_details.password}


def is_aic(node_type='gnb', node_id=0):
    if node_type != 'gnb':
        return False

    tl_config = get_testline_configuration()
    return tl_config is not None and \
        hasattr(tl_config.gnbs[node_id], 'cloud_deployment') and \
        tl_config.gnbs[node_id].cloud_deployment is not None  # needs to be checked for unit tests


def get_robot_variable(variable_name):
    """
    Returns the content of the given robot variable name.
    If robot is not running, an AssertionError will be thrown.

    :param variable_name: the robot variable name, i.e. '${tl}'
    """
    robot_builtin = BuiltIn.BuiltIn()
    try:
        return robot_builtin.get_variable_value(variable_name)
    except RobotNotRunningError:
        raise AssertionError("The library taf.ul.hanging_resources should be used in robot tests!")


def get_testline_configuration():
    """
    Returns the testline configuration from the current running robot context.
    If robot is not running, None will be returned.
    This library is to be expected to be used from robot keywords.
    Hence it will throw an Error, if used without a robot run.

    TODO: Give a descriptive error message, if the variable was not found!
    """
    global TL_CONFIG
    if TL_CONFIG is None:
        TL_CONFIG = get_robot_variable('${tl}')
        assert TL_CONFIG is not None, "The test should be run with a testline configuration!"
    return TL_CONFIG


def get_test_pcs_by_connection_objects(tl, nodeb):
    test_pcs = []
    nodeb_common_units = [common_unit for du in nodeb.dus for common_unit in du.airscale.common_units]
    for test_pc in tl.test_pcs:
        for connection in test_pc.connections:
            if hasattr(connection, 'device') and connection.device in nodeb_common_units:
                test_pcs.append(test_pc)
    test_pcs = list(set(test_pcs))
    return test_pcs


def get_test_pc_for_nodeb(tl, nodeb):
    """
    Determines the test pc by the given nodeb inside the given testline configuration.
    It is checked in the list of given test pcs, which test pc has an entry in its list of connections
    to the given nodeb. The corresponding test pc is returned. If no test pc was found, the first
    element of the test_pcs list in the testine configuration is returned.

    :param tl: The testlinec configuration
    :param nodeb: The nodeb configuration object in the testline config.
    """
    test_pcs = []

    if tl.test_pcs is None:
        return tl.test_pc

    uses_connection_object = any(hasattr(connection, 'device')
                                 for test_pc in tl.test_pcs for connection in test_pc.connections)

    if uses_connection_object:
        test_pcs = get_test_pcs_by_connection_objects(tl, nodeb)
    else:
        test_pcs = [test_pc for test_pc in tl.test_pcs for obj in test_pc.connections if obj is nodeb]

    if test_pcs:
        return test_pcs[0]

    logger.warning("test_pcs were not found and connecting to default test_pc")
    return tl.test_pc


def get_test_pc(node_id=0, node_type='gnb'):
    """
    This function determines the test pc in the testline configuration, depening on the given
    node_type and node_id

    :parm tl: The testline configuration
    :param node_id: The node_id which corresponds to the index in the testline config of tl.gnbs or tl.enbs
    :param node_type: The type of nodeB, can be 'enb' or 'gnb'
    """
    tl = get_testline_configuration()
    if node_type == 'gnb':
        return get_test_pc_for_nodeb(tl, tl.gnbs[node_id])
    elif node_type == 'enb':
        return get_test_pc_for_nodeb(tl, tl.enbs[node_id])

    raise AssertionError("Error in getting node: invalid node type {}".format(node_type))
